const items = $input.all();

const events = items.map(item => {
  const c = item.json;
  const message = c.commit?.message ?? "";

  return {
    source: "github",
    type: "commit",
    id: c.sha ?? null,
    timestamp: c.commit?.author?.date ?? null,
    author: c.author?.login ?? c.commit?.author?.name ?? null,
    title: message.split("\n")[0].trim(),
    message,
    url: c.html_url ?? null,
    repository: "priyanshukumarverma091-hub/RETRO-AI"
  };
});

const sortedEvents = events.sort((a, b) => {
  return new Date(a.timestamp || 0) - new Date(b.timestamp || 0);
});

const timeline = sortedEvents.map((event, index) => ({
  sequence: index + 1,
  timestamp: event.timestamp,
  author: event.author,
  title: event.title,
  type: event.type,
  source: event.source,
  url: event.url
}));

const decisions = sortedEvents.filter(event => {
  const text = `${event.title} ${event.message}`.toLowerCase();

  return (
    text.includes("decision") ||
    text.includes("decide") ||
    text.includes("chosen") ||
    text.includes("switch") ||
    text.includes("migrate") ||
    text.includes("use ")
  );
});

const pending = sortedEvents.filter(event => {
  const text = `${event.title} ${event.message}`.toLowerCase();

  return (
    text.includes("todo") ||
    text.includes("pending") ||
    text.includes("remaining") ||
    text.includes("next") ||
    text.includes("fix")
  );
});

const contributors = [...new Set(
  sortedEvents
    .map(event => event.author)
    .filter(Boolean)
)];

return [
  {
    json: {
      status: "context_reconstructed",
      repository: "priyanshukumarverma091-hub/RETRO-AI",
      generated_at: new Date().toISOString(),
      summary: {
        total_events: sortedEvents.length,
        contributors: contributors.length,
        first_event: sortedEvents[0]?.timestamp ?? null,
        latest_event: sortedEvents[sortedEvents.length - 1]?.timestamp ?? null,
        decision_count: decisions.length,
        pending_work_count: pending.length
      },
      contributors,
      timeline,
      decisions,
      pending_work: pending,
      current_state: {
        latest_activity: sortedEvents[sortedEvents.length - 1] ?? null,
        active_contributors: contributors,
        known_decisions: decisions.map(event => event.title),
        suspected_pending_work: pending.map(event => event.title)
      }
    }
  }
];

const context = $json;

const contextText = [
  `Repository: ${context.repository}`,
  `Total events: ${context.summary.total_events}`,
  `Contributors: ${context.summary.contributors}`,
  `First activity: ${context.summary.first_event}`,
  `Latest activity: ${context.summary.latest_event}`,
  `Decisions detected: ${context.summary.decision_count}`,
  `Pending work signals: ${context.summary.pending_work_count}`,
  `Contributors: ${context.contributors.join(", ")}`,
  "",
  "TIMELINE:",
  ...context.timeline.map(
    e => `${e.sequence}. ${e.timestamp} - ${e.author} - ${e.title}`
  ),
  "",
  "DECISIONS:",
  ...context.decisions.map(
    e => `- ${e.title}`
  ),
  "",
  "PENDING WORK:",
  ...context.pending_work.map(
    e => `- ${e.title}`
  )
].join("\n");

return [
  {
    json: {
      ...context,
      context_text: contextText
    }
  }
];
